+  border: 1px solid rgba(15,23,42,.10);
+  color: rgba(15,23,42,.80);
+  font-weight: 700;
+  font-size: 13px;
+}
+.badge strong{ color: var(--brand-ink); }
+
+.hero-card{
+  background: rgba(255,255,255,.88);
+  border: 1px solid rgba(15,23,42,.10);
+  border-radius: var(--radius-lg);
+  box-shadow: var(--shadow);
+  padding: 18px;
+}
+.hero-card h2{ margin: 0 0 10px; font-size: 14px; text-transform: uppercase; letter-spacing: .08em; color: rgba(15,23,42,.58); }
+.trust{ display:grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
+.trust-item{
+  background: linear-gradient(180deg, rgba(0,102,255,.08), rgba(255,255,255,.0));
+  border: 1px solid rgba(0,102,255,.12);
+  border-radius: 16px;
+  padding: 12px;
+}
+.trust-value{ font-size: 22px; font-weight: 900; letter-spacing: -0.02em; }
+.trust-label{ color: rgba(15,23,42,.70); font-weight: 650; font-size: 13px; }
