+  padding: 7px 10px;
+  font-weight: 800;
+  font-size: 12px;
+  cursor: pointer;
+}
+.geo-btn:hover{ background: rgba(0,102,255,.06); }
+
+.search-submit{
+  height: 100%;
+  min-height: 64px;
+  padding: 0 18px;
+  border-radius: 16px;
+}
+
+/* Autocomplete */
+.ac{
+  position:absolute;
+  left: 0;
+  right: 0;
+  top: calc(100% + 8px);
+  background: #fff;
+  border-radius: 16px;
+  border: 1px solid rgba(15,23,42,.12);
+  box-shadow: 0 18px 45px rgba(2, 6, 23, .14);
+  overflow: hidden;
+  display:none;
+  z-index: 20;
+}
