+.ac-item:hover, .ac-item.active{ background: rgba(0,102,255,.09); }
+.ac-icon{
+  width: 34px;
+  height: 34px;
+  border-radius: 12px;
+  display:flex;
+  align-items:center;
+  justify-content:center;
+  background: linear-gradient(135deg, rgba(0,102,255,.16), rgba(31,191,154,.14));
+  border: 1px solid rgba(0,102,255,.14);
+}
+.ac-title{ font-weight: 900; }
+.ac-meta{ font-size: 12px; color: rgba(15,23,42,.60); font-weight: 700; }
+
