+  border-radius: 22px;
+  background: #fff;
+  border: 1px solid rgba(15,23,42,.10);
+  overflow: hidden;
+}
+.phone-hero{ padding: 14px; background: linear-gradient(135deg, rgba(0,102,255,.16), rgba(31,191,154,.12)); }
+.phone-hero strong{ display:block; font-size: 14px; }
+.phone-hero span{ color: rgba(15,23,42,.68); font-weight: 700; font-size: 12px; }
+.phone-list{ padding: 10px; display:flex; flex-direction: column; gap: 10px; }
