+.mini-card b{ display:block; }
+.mini-card i{ font-style: normal; font-size: 12px; color: rgba(15,23,42,.62); font-weight: 750; }
+
+.store-row{ display:flex; flex-wrap: wrap; gap: 10px; margin-top: 16px; }
