+.store-badge span{ display:block; font-size: 11px; font-weight: 800; color: rgba(15,23,42,.58); }
+
+/* Footer */
+footer{ padding: 44px 0; background: #0b1220; color: rgba(255,255,255,.86); }
+.footer-grid{ display:grid; grid-template-columns: 1.2fr repeat(4, minmax(0, 1fr)); gap: 18px; }
+.footer-brand{ display:flex; gap: 10px; align-items:center; margin-bottom: 10px; }
+.footer-brand strong{ font-size: 16px; }
+.footer-col h5{ margin: 0 0 10px; font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: rgba(255,255,255,.62); }
+.footer-col a{ display:block; padding: 6px 0; color: rgba(255,255,255,.80); font-weight: 700; font-size: 13px; }
+.footer-col a:hover{ color: #fff; }
+.footer-bottom{ margin-top: 18px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.10); display:flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
+.footer-bottom p{ margin: 0; color: rgba(255,255,255,.70); font-weight: 650; font-size: 13px; }
+
+/* Results (mock) */
+.results{
+  margin-top: 14px;
+  border-radius: var(--radius-lg);
+  border: 1px dashed rgba(0,102,255,.30);
+  background: rgba(0,102,255,.06);
+  padding: 14px;
+}
+.results h3{ font-size: 16px; margin: 0 0 8px; }
+.results .row{ display:flex; flex-wrap: wrap; gap: 10px; align-items:center; }
+.pill{ display:inline-flex; align-items:center; gap: 8px; padding: 8px 10px; border-radius: 999px; background: #fff; border: 1px solid rgba(15,23,42,.10); font-weight: 900; font-size: 13px; }
+.pill code{ font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; font-size: 12px; }
+
+/* Responsive */
+@media (max-width: 940px){
+  .hero-grid{ grid-template-columns: 1fr; }
+  .hero-card{ order: 2; }
+  .search-panel form{ grid-template-columns: 1fr; }
+  .search-submit{ min-height: 56px; }
+  .grid-3{ grid-template-columns: repeat(2, minmax(0, 1fr)); }
+  .steps{ grid-template-columns: 1fr; }
+  .quotes{ grid-template-columns: 1fr; }
+  .app-promo{ grid-template-columns: 1fr; }
+  .footer-grid{ grid-template-columns: 1fr 1fr; }
+  .nav{ display:none; }
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{ scroll-behavior: auto !important; transition: none !important; }
+}
*** End Patch
PATCH

